module helical_thread(R_low, w_low, R_high, w_high, pitch, phi_start, phi_end, z_at_start, steps) {
    N = steps;
    pts = [ for(i=[0:N])
        let(
            phi = phi_start + (phi_end-phi_start)*i/N,
            zc = z_at_start + pitch*(phi-phi_start)/(2*PI),
            c = cos(phi), s = sin(phi)
        )
        each [
            [R_low*c, R_low*s, zc - w_low/2],
            [R_low*c, R_low*s, zc + w_low/2],
            [R_high*c, R_high*s, zc + w_high/2],
            [R_high*c, R_high*s, zc - w_high/2]
        ]
    ];
